import os,glob,numpy as np
for sd in sorted(glob.glob('/app/data/jm*/20*')):
 print('\n',sd.replace('/app/data/',''))
 for f in sorted(glob.glob(sd+'/**/*.npy',recursive=True)):
  try:
   a=np.load(f,allow_pickle=True,mmap_mode=None)
   if isinstance(a,np.ndarray):
    finite=np.isfinite(a) if a.dtype.kind in 'fciub' else None
    desc=f'shape={a.shape} dtype={a.dtype}'
    if a.size and finite is not None: desc+=f' min={np.nanmin(a):.4g} max={np.nanmax(a):.4g} nan={np.isnan(a).sum() if a.dtype.kind in "fc" else 0}'
   else: desc=type(a).__name__
   print(' ',os.path.relpath(f,sd),desc)
  except Exception as e: print(' ',os.path.relpath(f,sd),'ERROR',e)
